import { Avatar } from '@liulidesign/core/Avatar';

const photo = (n: number) => `public/avatars/avatar-${n}.png`;

/** A photo, and initials where there is none or it fails to load. */
export function People() {
  return (
    <view className="flex-row items-center gap-3">
      <Avatar name="Ana Lima" src={photo(1)} data-testid="ana" />
      <Avatar name="Kai Chen" data-testid="kai" />
      <Avatar name="Mira Patel" src="public/avatars/missing.png" data-testid="mira" />
    </view>
  );
}

import { Avatar } from '@liulidesign/core/Avatar';

export function Sizes() {
  return (
    <view className="flex-row items-center gap-3">
      <Avatar name="Ana Lima" size="xs" />
      <Avatar name="Ana Lima" size="sm" />
      <Avatar name="Ana Lima" size="md" />
      <Avatar name="Ana Lima" size="lg" />
    </view>
  );
}

import { Avatar, AvatarGroup } from '@liulidesign/core/Avatar';

const photo = (n: number) => `public/avatars/avatar-${n}.png`;

/** Overlapping, with the rest folded into a count. */
export function Group() {
  return (
    <AvatarGroup label="Editors" max={4} overflowLabel={count => `${count} more editors`} data-testid="editors">
      <Avatar name="Ana Lima" src={photo(1)} />
      <Avatar name="Kai Chen" />
      <Avatar name="Mira Patel" src={photo(2)} />
      <Avatar name="Tomás Ruiz" />
      <Avatar name="Lena Vogel" />
      <Avatar name="Sam Okafor" />
    </AvatarGroup>
  );
}

import { Avatar } from '@liulidesign/core/Avatar';

/** Beside the name it stands for, so it is decorative. */
export function WithName() {
  return (
    <view className="flex-row items-center gap-3">
      <Avatar name="Kai Chen" isDecorative />
      <view className="gap-0.5">
        <text className="text-body font-medium text-text">Kai Chen</text>
        <text className="text-footnote text-muted">Edited 2 minutes ago</text>
      </view>
    </view>
  );
}

import { Avatar } from '@liulidesign/core/Avatar';

const photo = (n: number) => `public/avatars/avatar-${n}.png`;

/** Whether each person is around, as a dot on the avatar and in words for a screen reader. */
export function Presence() {
  return (
    <view className="flex-row items-center gap-4">
      <Avatar name="Ana Lima" src={photo(1)} status="online" statusLabel="Online" data-testid="online" />
      <Avatar name="Kai Chen" status="away" statusLabel="Away" data-testid="away" />
      <Avatar name="Mira Patel" status="busy" statusLabel="Do not disturb" data-testid="busy" />
      <Avatar name="Sam Ortiz" status="offline" statusLabel="Offline" data-testid="offline" />
      <Avatar name="Design team" size="lg" status="online" statusLabel="3 online" />
    </view>
  );
}

import { Badge } from '@liulidesign/core/Badge';
import { Avatar } from '@liulidesign/core/Avatar';

/** A count on the avatar: unread messages from this person. */
export function Unread() {
  return <Avatar name="Kai Chen" badge={<Badge label="3" tone="danger" emphasis="solid" size="sm" />} data-testid="unread" />;
}

import { hueFor } from '../hue';
import { Avatar } from '@liulidesign/core/Avatar';

/** A rounded square for what is not a person: a team, a workspace. */
/** Each name gets its own hue, the same one every time, so a list of initials is not a column of one colour. */
export function Hues() {
  const people = ['Ana Lima', 'Kai Chen', 'Mira Patel', 'Tomas Reyes', 'Yuki Sato', 'Noor Haddad'];
  return (
    <view className="flex-row flex-wrap gap-3">
      {people.map(name => <Avatar key={name} name={name} hue={hueFor(name)} data-testid={`hue-${name.split(' ')[0].toLowerCase()}`} />)}
    </view>
  );
}

import { Badge } from '@liulidesign/core/Badge';

export function Tones() {
  return (
    <view className="flex-row flex-wrap gap-2">
      <Badge label="Draft" data-testid="neutral" />
      <Badge label="New" tone="accent" data-testid="accent" />
      <Badge label="Scheduled" tone="info" data-testid="info" />
      <Badge label="Paid" tone="success" />
      <Badge label="Due soon" tone="warning" />
      <Badge label="Overdue" tone="danger" data-testid="danger" />
    </view>
  );
}

import { Badge } from '@liulidesign/core/Badge';

/** Solid fills stand out; keep one per view. */
export function Solid() {
  return (
    <view className="flex-row flex-wrap gap-2">
      <Badge label="Beta" tone="accent" emphasis="solid" data-testid="solid" />
      <Badge label="Update" tone="info" emphasis="solid" />
      <Badge label="Live" tone="success" emphasis="solid" />
      <Badge label="Paused" tone="warning" emphasis="solid" />
      <Badge label="Failed" tone="danger" emphasis="solid" />
    </view>
  );
}

import { Badge } from '@liulidesign/core/Badge';

/** Kinds of things, not states: each project keeps its hue wherever it is named. */
export function Hues() {
  return (
    <view className="flex-row flex-wrap gap-2">
      <Badge label="Design" hue={1} data-testid="hue-1" />
      <Badge label="Research" hue={2} />
      <Badge label="Hardware" hue={3} />
      <Badge label="Field trials" hue={4} />
      <Badge label="Marketing" hue={5} />
      <Badge label="Legal" hue={6} />
      <Badge label="Support" hue={7} />
      <Badge label="Archive" hue={8} />
    </view>
  );
}

import { Badge } from '@liulidesign/core/Badge';

export function Sizes() {
  return (
    <view className="flex-row flex-wrap items-center gap-2">
      <Badge label="Small" size="sm" data-testid="small" />
      <Badge label="Online" tone="success" startIcon="success" />
    </view>
  );
}

import { Said } from '../example';
import { Item } from '@liulidesign/core/Item';
import { Badge } from '@liulidesign/core/Badge';

/** In a pressable row the end content is not read, so the status is repeated in the description. */
export function InARow() {
  return (
    <Said>
      {say => (
        <view className="overflow-hidden rounded-container border border-text/12 bg-surface">
          <Item
            label="Invoice 2041"
            description="Overdue, due 3 May"
            endContent={<Badge label="Overdue" tone="danger" size="sm" />}
            hasChevron
            onClick={() => say('Opened Invoice 2041')}
            data-testid="invoice"
          />
        </view>
      )}
    </Said>
  );
}

import { useLocal } from '@lingxia/view';
import { Banner } from '@liulidesign/core/Banner';

/** A problem with one way out, that the person can also put aside. */
export function Payment() {
  const shown = useLocal(true);
  const updated = useLocal(false);
  if (!shown.value) return <text className="text-footnote text-muted">Dismissed. It comes back on the next visit.</text>;
  return (
    <Banner
      tone="warning"
      title="Your card expires this month"
      message="Update it before 30 June to keep syncing across devices."
      action={{ label: updated.value ? 'Card updated' : 'Update card', onClick: () => updated.set(true) }}
      onDismiss={() => shown.set(false)}
      dismissLabel="Dismiss"
      data-testid="payment"
    />
  );
}

import { Banner } from '@liulidesign/core/Banner';

export function Tones() {
  return (
    <view className="gap-3">
      <Banner tone="neutral" title="Read only" message="An admin locked this notebook." />
      <Banner tone="info" title="Sharing is changing" message="From July, shared notebooks need a Team plan." />
      <Banner tone="success" title="All notes synced" />
      <Banner tone="warning" title="Storage almost full" message="You have used 9.6 of 10 GB." />
      <Banner tone="danger" title="Sync stopped" message="We could not reach the server. Your changes are kept on this device." />
    </view>
  );
}

import { useLocal } from '@lingxia/view';
import { Banner } from '@liulidesign/core/Banner';

/** At the top of a list it is about, before the content. */
export function OverList() {
  const retried = useLocal(false);
  return (
    <view className="gap-3">
      <Banner
        tone="danger"
        title={retried.value ? 'Still offline' : 'Sync stopped'}
        message="Changes are kept on this device until the connection returns."
        action={{ label: 'Retry now', onClick: () => retried.set(true) }}
        data-testid="sync"
      />
      <view className="overflow-hidden rounded-container border border-text/12 bg-surface divide-y divide-text/8">
        {['Q3 plan', 'Reading list', 'Interview notes'].map(note => (
          <view key={note} className="px-4 py-3"><text className="text-body text-text">{note}</text></view>
        ))}
      </view>
    </view>
  );
}

import { Said } from '../example';
import { Banner } from '@liulidesign/core/Banner';

/** Folded to its title until someone wants the rest: for a notice that stays for days. */
export function Collapsible() {
  return (
    <Said>
      {say => (
        <Banner
          tone="warning"
          title="Scheduled maintenance on Sunday"
          message="Sync pauses from 02:00 to 04:00 UTC. Notes you write then are kept on this device and sent when it ends."
          action={{ label: 'See the schedule', onClick: () => say('Opened the schedule') }}
          isCollapsible
          toggleLabel="Details"
          isDefaultOpen={false}
          data-testid="maintenance"
        />
      )}
    </Said>
  );
}

import { useLocal } from '@lingxia/view';
import { Button } from '@liulidesign/core/Button';
import { Item, ItemList } from '@liulidesign/core/Item';
import { BottomSheet } from '@liulidesign/core/BottomSheet';

const moveTargets = ['Inbox', 'Travel', 'Work', 'Recipes'];

/** Choosing where a note goes: a sheet as tall as its list, dragged down or tapped outside to cancel. */
export function MoveTo() {
  const open = useLocal('open', false);
  const folder = useLocal('folder', 'Inbox');
  return (
    <view className="gap-3">
      <Button label="Move note" width="content" onClick={() => open.set(true)} data-testid="move-open" />
      <text className="text-footnote text-muted" data-testid="folder">{`In ${folder.value}`}</text>
      <BottomSheet isOpen={open.value} onOpenChange={next => open.set(next)} label="Move to" data-testid="move">
        <ItemList label="Folders">
          {moveTargets.map(name => (
            <Item key={name} label={name} onClick={() => { folder.set(name); open.set(false); }} data-testid={`folder-${name}`} />
          ))}
        </ItemList>
      </BottomSheet>
    </view>
  );
}

import { useLocal } from '@lingxia/view';
import { Button } from '@liulidesign/core/Button';
import { BottomSheet } from '@liulidesign/core/BottomSheet';

const comments = [
  ['Ana', 'Can we move the review to Thursday?'],
  ['Kai', 'Thursday works. I will update the plan.'],
  ['Mira', 'Added the budget numbers under Q3.'],
  ['Ana', 'Thanks. The hiring section still needs dates.'],
  ['Kai', 'I will add them after the sync.'],
  ['Mira', 'Linked the research notes as well.'],
] as const;

/** A long list: the sheet opens halfway and drags up to nearly the full height. */
export function Comments() {
  const open = useLocal('open', false);
  return (
    <view className="gap-3">
      <Button label="Show comments" width="content" onClick={() => open.set(true)} data-testid="comments-open" />
      <BottomSheet
        isOpen={open.value}
        onOpenChange={next => open.set(next)}
        label="Comments"
        closeLabel="Close"
        detents="expandable"
        data-testid="comments"
      >
        {comments.map(([who, text], index) => (
          <view key={`c${index}`} className="gap-0.5">
            <text className="text-footnote font-semibold text-text">{who}</text>
            <text className="text-body text-text">{text}</text>
          </view>
        ))}
      </BottomSheet>
    </view>
  );
}

import { useLocal } from '@lingxia/view';
import { Button } from '@liulidesign/core/Button';
import { BottomSheet } from '@liulidesign/core/BottomSheet';

/** A step that must be answered: no drag off, no tap outside. */
export function Required() {
  const open = useLocal('open', false);
  const answer = useLocal('answer', '');
  return (
    <view className="gap-3">
      <Button label="Leave notebook" variant="destructive" width="content" onClick={() => open.set(true)} data-testid="leave-open" />
      {answer.value !== '' && <text className="text-footnote text-muted" data-testid="answer">{answer.value}</text>}
      <BottomSheet
        isOpen={open.value}
        onOpenChange={next => open.set(next)}
        label="Leave this notebook?"
        description="You lose access to its notes until someone invites you again."
        dismissOn="none"
        data-testid="leave"
        actions={
          <>
            <Button label="Stay" onClick={() => { answer.set('Stayed'); open.set(false); }} data-testid="stay" />
            <Button label="Leave" variant="destructive" onClick={() => { answer.set('Left'); open.set(false); }} data-testid="leave-confirm" />
          </>
        }
      />
    </view>
  );
}

import { useLocal } from '@lingxia/view';
import { Breadcrumb } from '@liulidesign/core/Breadcrumb';

/** Where a file sits: each level above it is a way back. */
export function Path() {
  const opened = useLocal('opened', '');
  const go = (name: string) => () => opened.set(name);
  return (
    <view className="gap-2">
      <Breadcrumb
        label="Breadcrumb"
        items={[
          { key: 'home', label: 'Home', onClick: go('Home') },
          { key: 'projects', label: 'Projects', onClick: go('Projects') },
          { key: 'plan', label: 'Q3 plan' },
        ]}
        data-testid="path"
      />
      {opened.value !== '' && <text role="status" className="text-footnote text-muted">{`Opened ${opened.value}`}</text>}
    </view>
  );
}

import { Said } from '../example';
import { Breadcrumb } from '@liulidesign/core/Breadcrumb';

/** A deep trail: the middle levels fold into a menu, and the first level and the last two stay. */
export function Deep() {
  return (
    <Said>
      {say => (
        <Breadcrumb
          label="Breadcrumb"
          moreLabel="More levels"
          items={[
            { key: 'drive', label: 'Drive', onClick: () => say('Opened Drive') },
            { key: 'clients', label: 'Clients', onClick: () => say('Opened Clients') },
            { key: 'northwind', label: 'Northwind', onClick: () => say('Opened Northwind') },
            { key: '2026', label: '2026', onClick: () => say('Opened 2026') },
            { key: 'invoices', label: 'Invoices', onClick: () => say('Opened Invoices') },
            { key: 'inv', label: 'INV-1043.pdf' },
          ]}
          data-testid="deep"
        />
      )}
    </Said>
  );
}

import { Said } from '../example';
import { Button } from '@liulidesign/core/Button';

export function Variants() {
  return (
    <Said>
      {say => (
        <view className="flex-row flex-wrap gap-2">
          <Button label="Save changes" variant="primary" onClick={() => say('Saved changes')} data-testid="primary" />
          <Button label="Preview" onClick={() => say('Opened the preview')} />
          <Button label="Skip" variant="ghost" onClick={() => say('Skipped')} />
          <Button label="Delete draft" variant="destructive" onClick={() => say('Deleted the draft')} />
        </view>
      )}
    </Said>
  );
}

import { Said } from '../example';
import { Button } from '@liulidesign/core/Button';

export function Sizes() {
  return (
    <Said>
      {say => (
        <view className="flex-row flex-wrap items-center gap-2">
          <Button label="Small" size="sm" onClick={() => say('Chose Small')} />
          <Button label="Medium" onClick={() => say('Chose Medium')} />
