import { Said } from '../example';
import { Button } from '@liulidesign/core/Button';
import { IconButton } from '@liulidesign/core/IconButton';
import { ButtonGroup } from '@liulidesign/core/ButtonGroup';

/** A toolbar over content: icon buttons in a quiet group, a labelled action apart from it. */
export function Toolbar() {
  return (
    <Said>
      {say => (
        <view className="flex-row flex-wrap items-center justify-between gap-3">
          <ButtonGroup label="Message actions" size="sm" data-testid="message">
            <IconButton label="Reply" icon="message" onClick={() => say('Replied')} />
            <IconButton label="Forward" icon="send" onClick={() => say('Forwarded')} />
            <IconButton label="Delete" icon="delete" onClick={() => say('Deleted the message')} />
          </ButtonGroup>
          <Button label="Archive" size="sm" startIcon="folder" onClick={() => say('Archived the message')} />
        </view>
      )}
    </Said>
  );
}

import { useLocal } from '@lingxia/view';
import { Calendar } from '@liulidesign/core/Calendar';
import { calendarEn } from './locale/en';

const today = '2026-11-15';

/** One day: the chosen day is filled, today is ringed. */
export function Day() {
  const day = useLocal<string | null>('day', '2026-11-19');
  return <Calendar label="Due date" locale={calendarEn} value={day.value} onChange={day.set} today={today} data-testid="due" />;
}

import { useLocal } from '@lingxia/view';
import { Calendar, type CalendarRange } from '@liulidesign/core/Calendar';
import { calendarEn } from './locale/en';

const today = '2026-11-15';

/** A span: the first press starts it, the second ends it. Days before today cannot be chosen. */
export function Stay() {
  const stay = useLocal<CalendarRange>('stay', { start: '2026-11-18', end: '2026-11-24' });
  return (
    <view className="gap-2">
      <Calendar label="Stay" locale={calendarEn} isRange value={stay.value} onChange={stay.set} min={today} today={today} data-testid="stay" />
      <text role="status" className="px-2 text-footnote text-muted tabular-nums">{`${stay.value.start ?? ''} – ${stay.value.end ?? ''}`}</text>
    </view>
  );
}

